    \"\"\"Write uncompressed ZIPs and skip members already staged.\"\"\"
    def __init__(self):
        self.zipfiles = {}

    def get_zipfile(self, name):
        match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.([A-Za-z0-9]+)', name)
        if not match:
            raise ValueError('invalid cover filename')
        item_id, batch_id = Cover.id_to_item_and_batch_id(match.group(1))
        path = Batch.get_abspath(item_id, batch_id, (match.group(2) or '').lower())
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED)
            self.zipfiles[path] = zf, set(zf.namelist())
        return self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        zf, names = self.get_zipfile(name)
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            names.add(name)
        return name

    def close(self):
        for zf, _ in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()


